const affiliateTag = $env.AMAZON_AFFILIATE_TAG || 'dealon04-21';
const results = [];

for (const item of $input.all()) {
  const p = item.json;
  const currentPrice = Number(p.current_price);
  const targetDropPrice = Number(p.target_drop_price);
  const historicalLow = Number(p.historical_low);
  const mrp = Number(p.mrp);
  const isLow = p.is_historical_low || currentPrice <= historicalLow;

  // Evaluation condition: Trigger alert if current price hits target drop threshold
  const shouldAlert = currentPrice <= targetDropPrice;

  if (shouldAlert) {
    const savings = mrp - currentPrice;
    const discount = Math.round(((mrp - currentPrice) / mrp) * 100);
    const affiliateUrl = `https://www.amazon.in/dp/${p.asin}?tag=${affiliateTag}`;
    const badgeHeader = isLow ? '🔥 *HISTORICAL ALL-TIME LOW ALERT*' : '⚡ *PRICE DROP ALERT*';

    // High-converting formatted Markdown message for Telegram
    const message = `${badgeHeader}\n\n` +
      `📦 *${p.title}*\n` +
      `🏢 *Brand:* ${p.brand} | 🏷️ #${p.category.replace(/\s+/g, '')}\n\n` +
      `💰 *Deal Price:* ₹${currentPrice.toLocaleString('en-IN')}\n` +
      `❌ *MRP:* ~₹${mrp.toLocaleString('en-IN')}~\n` +
      `📉 *Savings:* ₹${savings.toLocaleString('en-IN')} (${discount}% OFF)\n` +
      `🎯 *Historical 90D Low:* ₹${historicalLow.toLocaleString('en-IN')}\n\n` +
      `👉 *Grab Deal on Amazon:*\n${affiliateUrl}\n\n` +
      `🔔 Tracked 24/7 by @dealon\_offers | DealOn Portal`;

    results.push({
      json: {
        ...p,
        affiliate_url: affiliateUrl,
        formatted_message: message,
        should_alert: true,
        button_text: `🛒 Buy on Amazon (₹${currentPrice})`
      }
    });
  }
}

return results;
